<?php
require_once dirname(__DIR__) . '/middleware/bootstrap.php';
require_role('admin');
$db=Database::connection();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['user_id']??0);$active=(int)($_POST['active']??0);if($id!==current_user_id()){$stmt=$db->prepare("UPDATE users SET active=? WHERE id=? AND role='student'");$stmt->execute([$active,$id]);$db->prepare('INSERT INTO audit_logs(actor_user_id,action,entity_type,entity_id,ip_address) VALUES(?,?,?,?,?)')->execute([current_user_id(),$active?'student_activated':'student_deactivated','user',$id,$_SERVER['REMOTE_ADDR']??null]);flash('success','Student account updated.');}else flash('danger','You cannot change your own administrator account here.');redirect('admin/students.php');}
$q=trim((string)($_GET['q']??''));$sql='SELECT s.*,u.id user_id,u.email,u.active,d.name department_name FROM students s JOIN users u ON u.id=s.user_id JOIN departments d ON d.id=s.department_id';$params=[];if($q!==''){$sql.=' WHERE s.full_name LIKE ? OR s.register_number LIKE ? OR u.email LIKE ?';$n='%'.$q.'%';$params=[$n,$n,$n];}$sql.=' ORDER BY s.full_name LIMIT 500';$stmt=$db->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();
page_start('Students','admin/students.php');
?>
<div class="content-width"><?php page_title('Students','Search, review, and manage student accounts.'); ?><div class="panel mb-3"><form class="d-flex gap-2"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Name, register number, or email"><button class="btn btn-outline-primary">Search</button></form></div><div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Student</th><th>Register number</th><th>Department</th><th>Semester / Year</th><th>Courses</th><th>Account</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $s): ?><tr><td><strong><?= e($s['full_name']) ?></strong><div class="small text-muted"><?= e($s['email']) ?></div></td><td><?= e($s['register_number']) ?></td><td><?= e($s['department_name']) ?></td><td><?= (int)$s['semester'] ?> · <?= e($s['academic_year']) ?></td><td><?php $count=$db->prepare("SELECT COUNT(*) FROM registrations WHERE student_id=? AND status IN ('pending','approved')");$count->execute([$s['id']]);echo (int)$count->fetchColumn(); ?></td><td><span class="badge text-bg-<?= $s['active']?'success':'secondary' ?>"><?= $s['active']?'Active':'Inactive' ?></span></td><td class="table-actions"><a class="btn btn-sm btn-outline-primary" href="<?= e(url('admin/student_form.php?id='.(int)$s['id'])) ?>">Edit</a> <form class="d-inline" method="post" data-confirm-submit="Change this student account status?"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$s['user_id'] ?>"><input type="hidden" name="active" value="<?= $s['active']?0:1 ?>"><button class="btn btn-sm btn-outline-secondary"><?= $s['active']?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="7"><div class="empty-state"><h3>No students found</h3></div></td></tr><?php endif; ?></tbody></table></div></div></div>
<?php page_end(); ?>
